// The effect ratings (packages/engine/src/ratings.js) are generated by scripts/effect-score.js --write, which takes
// minutes. These checks are cheap: the ratings must cover exactly the built-in effects, match their sources (a hash in
// the file's header), keep the contract the director codes against, and AUTO may only pick existing effects with the
// role's tag. When this fails after changing effects.js: node scripts/effect-score.js --write
import { test } from "node:test";
import assert from "node:assert/strict";
import { RATINGS, AUTO, rating } from "../src/index.js";
import { checkRatings, builtinEffects, effectSources } from "../../../scripts/effect-score.js";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

test("ratings.js is up to date with effects.js (node scripts/effect-score.js --write)", async () => {
  const r = await checkRatings();
  assert.ok(r.ok, `ratings.js is stale:\n  ${r.problems.join("\n  ")}\nrun: node scripts/effect-score.js --write`);
});

test("every built-in effect's source is found for the staleness hash", () => {
  const src = effectSources(readFileSync(fileURLToPath(new URL("../src/effects.js", import.meta.url)), "utf8"));
  for (const e of builtinEffects()) assert.ok(src.has(e.id) && src.get(e.id).includes("run("), `source of ${e.id}`);
});

test("ratings keep their contract", () => {
  const ids = builtinEffects().map(e => e.id);
  assert.deepEqual(Object.keys(RATINGS).sort(), ids.slice().sort());
  for (const [id, r] of Object.entries(RATINGS)) {
    for (const k of ["drop", "build", "calm"]) assert.ok(Number.isInteger(r[k]) && r[k] >= 0 && r[k] <= 100, `${id}.${k}`);
    assert.ok(Array.isArray(r.tempo) && r.tempo.length === 2 && r.tempo[0] < r.tempo[1], `${id}.tempo`);
    assert.ok(["low", "mid", "high"].includes(r.energy), `${id}.energy`);
    assert.equal(typeof r.kickDriven, "boolean"); assert.equal(typeof r.needsBeat, "boolean");
    assert.ok(r.busy >= 0 && r.busy <= 1, `${id}.busy`);
  }
  assert.equal(rating("shock"), RATINGS.shock);
  assert.equal(rating("my-custom-effect"), null);
  assert.equal(rating("toString"), null);
});

test("AUTO: curated picks of existing effects with the role's tag, best first", () => {
  const tag = Object.fromEntries(builtinEffects().map(e => [e.id, e.tag])), size = { drop: [12, 15], build: [6, 8], calm: [6, 8] };
  for (const role of ["drop", "build", "calm"]) {
    const list = AUTO[role];
    assert.ok(list.length >= size[role][0] && list.length <= size[role][1], `AUTO.${role} has ${list.length}`);
    assert.equal(new Set(list).size, list.length, `AUTO.${role} has no repeats`);
    for (const id of list) assert.equal(tag[id], role, `AUTO.${role}: ${id} is tagged ${tag[id]}`);
    for (let i = 1; i < list.length; i++) assert.ok(RATINGS[list[i - 1]][role] >= RATINGS[list[i]][role], `AUTO.${role} is best first`);
  }
});
